/* generated child CSS: 03-cta/cta.btn-base/block.css */
/* lab-ui block · cta.btn-base
   Depends: 00-tokens/tokens.css (--radius-pill, --font-family,
   --transition-duration). Shared geometry + .btn-star base for every
   CTA variant. Variant blocks (cta.btn-primary-ring,
   cta.btn-secondary-filled) layer their own ::before/::after, halo
   shadows and color tokens on top. */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-width: 13rem;
  height: 3.25rem;
  padding: 0 1.625rem;
  border-radius: var(--radius-pill);
  font-family: var(--font-family);
  font-weight: 500;
  font-size: 1rem;
  white-space: nowrap;
  position: relative;
  text-decoration: none;
  cursor: pointer;
  border: 0;
  transition: box-shadow var(--transition-duration) ease,
              transform var(--transition-duration) ease;
}

.btn-star {
  flex-shrink: 0;
  transition: transform var(--transition-duration) cubic-bezier(.4, 0, .2, 1);
}


/* generated child CSS: 12-decorative/effect.hover-rise/block.css */
/* ============================================================
   lab-ui block · effect.hover-rise
   ----------------------------------------------------------------
   Brand interaction primitive — standard CTA halo + inner bottom-glow
   that fades in on :hover. Applied via CSS, no markup.

   ## Where it auto-applies (brand primitives)
   - .btn-primary-ring          (cta.btn-primary-ring)
   - .btn-secondary-filled      (cta.btn-secondary-filled)
   - .nav-link, .nav-trigger    (header.default nav items)
   - .locale-trigger            (language.locale-dropdown)
   - .bc-link                   (header.default breadcrumb)

   ## Opt-in for custom elements
   - [data-fx="rise"]

   ## Tint
   Default uses --cta-accent (which is --color-cyan by default and
   re-themed via [data-theme="..."] overlays). Override per element
   via --fx-rise-color: <color>.

   ## Implementation
   Each target element gets a ::after pseudo with the canonical
   bottom-centered radial glow used by current CTA blocks, plus an
   outer hover halo via box-shadow. No external image asset.

   ## Stacking
   Container must be position:relative (or rely on the host block
   making itself relative — all brand-primitive blocks already do).
   The ::after is z-index:1 with pointer-events:none so it never
   blocks interaction.
   ============================================================ */

:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
)::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
  border-radius: inherit;
  opacity: 0;
  transition: opacity var(--transition-duration, 0.25s) ease;

  /* Canonical inner glow: same bottom-centered radial used by
     cta.btn-primary-ring and cta.btn-secondary-filled. */
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--fx-rise-color, var(--cta-accent, #6BEAF9)) 0%,
    transparent 60%
  );
  mix-blend-mode: normal;
  filter: none;
}

/* Activate on hover + on keyboard focus-visible (a11y). */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):is(:hover, :focus-visible)::after {
  opacity: 0.48;
}

/* Brand-primitive base — they all need to be relative for the
   ::after to anchor inside. Each block also sets this in its own
   block.css, but we re-declare here so the effect works even when
   only this CSS is imported. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) {
  position: relative;
  overflow: hidden;
  transition:
    box-shadow var(--transition-duration, 0.25s) ease,
    transform var(--transition-duration, 0.25s) ease;
}

/* Outer halo — two intensities so the same effect doesn't look
   aggressive on a 32 px nav link AND on a 52 px pill button.

   Strong (default): pills, cards, opt-in via [data-fx="rise"].
   Soft: header chrome — nav links, dropdown triggers, breadcrumb,
   locale chip. Override per element via --fx-rise-color. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  [data-fx="rise"]
):is(:hover, :focus-visible) {
  box-shadow: 0 0 32px -4px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

:where(
  .nav-link,
  .nav-trigger,
  .locale-trigger
):is(:hover, :focus-visible) {
  box-shadow: 0 0 18px -6px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

/* Keyboard-only focus ring (a11y). Distinct from the hover halo so that
   keyboard navigation is unambiguously visible — sighted hover users do
   not get the ring, only the soft glow. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):focus-visible {
  outline: 2px solid var(--fx-rise-color, var(--cta-accent, #6BEAF9));
  outline-offset: 2px;
}

/* The hover-rise must stay BEHIND the element's own contents.
   We use overflow:hidden + ::after with z-index 1 — content sits
   at z-index 2. Brand primitives bump their direct children to
   z-index 2 here so we don't have to touch every block.css. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) > * {
  position: relative;
  z-index: 2;
}

/* Reduced-motion: keep the effect but kill the transition so it
   appears instantly on hover with no animation. */
@media (prefers-reduced-motion: reduce) {
  :where(
    .btn-primary-ring,
    .btn-secondary-filled,
    .nav-link,
    .nav-trigger,
    .locale-trigger,
    .bc-link,
    [data-fx="rise"]
  )::after {
    transition: none;
  }
}


/* generated child CSS: 03-cta/cta.btn-primary-ring/block.css */
/* lab-ui block · cta.btn-primary-ring
   Depends: 00-tokens/tokens.css (--color-black, --radius-pill,
   --font-family, --gradient-cta-ring, --transition-duration,
   --cta-accent, --cta-accent-soft) + 03-cta/cta.btn-base (.btn, .btn-star). */

.btn-primary {
  background: var(--button-primary-bg, transparent);
  color: var(--button-primary-color, var(--color-black));
}

.btn-primary-ring {
  position: relative;
  overflow: hidden;
}

.btn-primary-ring::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  background: var(--gradient-cta-ring);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  pointer-events: none;
  z-index: 3;                          /* above hover-rise ::after */
  transition: background var(--transition-duration) ease;
}

/* On hover the rainbow ring rotates direction 249° → 264° (matches
   live the platform .button-primary:hover::before). */
.btn-primary-ring:hover::before {
  background: linear-gradient(
    264.85deg,
    rgba(239, 92, 255, 0)   -6.54%,
    #FFA72C                 24.73%,
    #6BEDF9                 70.73%,
    rgba(107, 237, 249, 0) 113.1%
  );
}

/* Outer brand glow on hover — tighter than sw's stock 41 px so it
   reads as a halo hugging the pill, not a rectangular smear behind
   it (matches the production reference). Tinted by --cta-accent so
   each vertical paints its own color. */
.btn-primary-ring:hover {
  box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
}

/* Match cta.btn-secondary-filled's hover affordance: a tighter
   bottom-centered radial glow that fades in, instead of the shared
   effect.hover-rise strip. The ring remains on ::before above it.
   Keep normal blending so the glow stays visible on white buttons. */
.btn-primary-ring::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: none;
  border-radius: inherit;
  pointer-events: none;
  z-index: 1;
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--cta-accent, #6BEAF9) 0%,
    transparent 60%
  );
  opacity: 0;
  filter: none;
  background-blend-mode: normal;
  mix-blend-mode: normal;
  transition: opacity var(--transition-duration) ease;
}

.btn-primary-ring:hover::after {
  opacity: 0.48;
}

.btn-primary-ring:hover .btn-star {
  transform: rotate(180deg);
}


/* generated child CSS: 01-header/header.corporate-reference/block.css */
/* lab-ui block · header.corporate-reference
   Imported from CMS BlockTemplate 5ef64a49-2d1c-44df-873f-8e6f471e4b38 (HEADER). */

/* Source root reset/utilities scoped to imported header chrome. */
.header *,
.header *::before,
.header *::after {
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}

.header :where(ul, ol):where([class]) {
  padding-left: 0;
}

.header :where(h1, h2, h3, h4, h5, h6, p, ul, ol, dl):where([class]) {
  margin-block: 0;
}

.header :where(ul[class]) {
  list-style: none;
}

.header a:where([class]) {
  display: -webkit-inline-box;
  display: -ms-inline-flexbox;
  display: inline-flex;
}

.header a {
  color: var(--color-link);
  text-decoration: none;
}

.header :where(input, textarea, select, button) {
  font: inherit;
}

.header :where(button, label) {
  cursor: pointer;
}

.header :where(button) {
  -webkit-tap-highlight-color: transparent;
}

.header svg * {
  -webkit-transition-property: fill, stroke;
  -o-transition-property: fill, stroke;
  transition-property: fill, stroke;
}

.sr-only {
	clip: rect(0 0 0 0);
	-webkit-clip-path: inset(50%);
	clip-path: inset(50%);
	height: 1px;
	overflow: hidden;
	position: absolute;
	white-space: nowrap;
	width: 1px;
}

/* Source root mobile header-height variables used by imported HEADER. */
@media (width < 120rem) {
  :root {
    --header-height: 4.375rem;
  }
}

@media (width < 80rem) {
  :root {
    --header-height: 3.75rem;
  }
}

@media (width < 48rem) {
  :root {
    --header-height: 3.125rem;
  }
}

/* ─── Header ─────────────────────────────────── */
.header {
	position: sticky;
	top: 0;
	left: 0;
	width: 100%;
	z-index: 50;
	display: -webkit-box;
	display: -ms-flexbox;
	display: flex;
	-webkit-box-orient: vertical;
	-webkit-box-direction: normal;
	-ms-flex-direction: column;
	flex-direction: column;
	background-color: var(--header-bg);
	backdrop-filter: blur(var(--backdrop-blur-header));
	-webkit-backdrop-filter: blur(var(--backdrop-blur-header));
	border-bottom-left-radius: 2.5rem;
	border-bottom-right-radius: 2.5rem;
	overflow: visible;
    transition: background-color var(--transition-duration) ease;
}

.header-container {
	width: 100%;
}

.header-top {
	display: -webkit-box;
	display: -ms-flexbox;
	display: flex;
	-webkit-box-pack: justify;
	-ms-flex-pack: justify;
	justify-content: space-between;
	-webkit-box-align: center;
	-ms-flex-align: center;
	align-items: center;
	height: var(--header-height);
	-webkit-column-gap: 1.25rem;
	-moz-column-gap: 1.25rem;
	column-gap: 1.25rem;
	-ms-flex-negative: 0;
	flex-shrink: 0;
}

.header-mobile-menu {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-orient: vertical;
  -webkit-box-direction: normal;
  -ms-flex-direction: column;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 0;
  opacity: 0;
  pointer-events: none;
  -webkit-transition: max-height var(--transition-duration) ease,
      opacity var(--transition-duration) ease,
      padding var(--transition-duration) ease;
  -o-transition: max-height var(--transition-duration) ease,
      opacity var(--transition-duration) ease,
      padding var(--transition-duration) ease;
  transition: max-height var(--transition-duration) ease,
      opacity var(--transition-duration) ease,
      padding var(--transition-duration) ease;
}

.header.is-open .header-mobile-menu {
	max-height: 31.25rem;
	opacity: 1;
	pointer-events: auto;
	padding-bottom: 1.25rem;
}

.mobile-menu-list {
	display: -webkit-box;
	display: -ms-flexbox;
	display: flex;
	-webkit-box-orient: vertical;
	-webkit-box-direction: normal;
	-ms-flex-direction: column;
	flex-direction: column;
	-webkit-box-align: center;
	-ms-flex-align: center;
	align-items: center;
	gap: 1.25rem;
	padding-top: 1.25rem;
    padding-right: 0;
}

.mobile-menu-link {
	display: block;
	font-weight: 500;
	color: var(--color-link);
	text-align: center;
}

.mobile-menu-button {
	max-width: fit-content;
	width: 100%;
	margin-top: 2.5rem;
	-webkit-box-pack: center;
	-ms-flex-pack: center;
	justify-content: center;
	margin-inline: auto;
}

.header-button.btn,
.mobile-menu-button.btn {
  gap: 0;
  min-width: 13.8125rem;
  height: auto;
  padding: 1.0625rem 1.625rem;
  border-radius: var(--radius-pill);
  font-weight: 500;
  font-size: 1.25rem;
  line-height: 1.3;
  letter-spacing: 0%;
}

.header-button.btn {
  flex-shrink: 0;
}

.header-button.btn .btn-star,
.mobile-menu-button.btn .btn-star {
  flex-shrink: 0;
  width: 1.3125rem;
  height: auto;
  aspect-ratio: 1;
}

[dir="ltr"] .header-button.btn .btn-star,
[dir="ltr"] .mobile-menu-button.btn .btn-star {
  margin-right: 0.5rem;
}

[dir="rtl"] .header-button.btn .btn-star,
[dir="rtl"] .mobile-menu-button.btn .btn-star {
  margin-left: 0.5rem;
}

@media (width < 120rem) {
  .header-button.btn,
  .mobile-menu-button.btn {
    font-weight: 400;
    font-size: 1rem;
  }
}

.mob-ind-overlay *,
.mob-ind-overlay *::before,
.mob-ind-overlay *::after {
  box-sizing: border-box;
}

.mob-ind-overlay :where(ul, h3, p) {
  margin: 0;
}

.mob-ind-overlay {
  height: 100dvh;
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.mob-ind-overlay.is-open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.mob-ind-sheet {
  width: 100%;
  max-width: 600px;
  min-height: 60dvh;
  max-height: 90dvh;
  background: var(--locale-selector-bg);
  border-radius: 1.25rem 1.25rem 0 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transform: translateY(100%);
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 -8px 48px rgba(0, 0, 0, 0.3);
}

.mob-ind-overlay.is-open .mob-ind-sheet {
  transform: translateY(0);
}

.mob-ind-views-outer {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.mob-ind-views {
  display: flex;
  width: 200%;
  height: 100%;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.mob-ind-views.detail-open {
  transform: translateX(-50%);
}

.mob-ind-view {
  width: 50%;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.mob-ind-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.mob-ind-topbar {
  display: flex;
  align-items: center;
  padding: 0.875rem 1.25rem;
  border-bottom: 1px solid var(--card-border);
  flex-shrink: 0;
  gap: 0.5rem;
}

.mob-ind-topbar-title {
  flex: 1;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-heading);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mob-ind-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: none;
  background: none;
  cursor: pointer;
  color: var(--color-heading);
  border-radius: 50%;
  flex-shrink: 0;
  transition: background-color 0.18s ease;
}

.mob-ind-btn:hover {
  background: var(--res-item-hover);
}

.mob-ind-navlist {
  list-style: none;
  padding: 0.5rem 0;
}

.mob-ind-navitem {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.75rem 1.25rem;
  cursor: pointer;
  color: var(--color-heading);
  transition: background-color 0.18s ease;
  user-select: none;
}

.mob-ind-navitem:hover {
  background: var(--res-item-hover);
}

.mob-ind-navitem.is-disabled {
  opacity: 0.45;
  pointer-events: none;
}

.mob-ind-navicon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ind-accent);
}

.mob-ind-navlabel {
  flex: 1;
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1.3;
}

.mob-ind-navarrow {
  flex-shrink: 0;
  color: var(--color-gray);
  opacity: 0.5;
}

.mob-ind-explore {
  border-top: 1px solid var(--card-border);
  padding: 1.5rem 1.25rem 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.5rem;
}

.mob-ind-explore-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--ind-accent-soft);
  color: var(--ind-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.25rem;
}

.mob-ind-explore-icon svg {
  color: var(--ind-accent);
  stroke: var(--ind-accent);
}

.mob-ind-explore-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-heading);
  margin-bottom: 0.125rem;
}

.mob-ind-explore-desc {
  font-size: 0.875rem;
  color: var(--res-desc);
  max-width: 280px;
  line-height: 1.5;
}

.mob-ind-explore-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  margin-top: 0.625rem;
  padding: 0.5625rem 1.375rem;
  border: 1.5px solid var(--ind-accent);
  border-radius: 100px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--ind-accent);
  text-decoration: none;
  transition: background-color 0.2s ease;
}

.mob-ind-explore-cta:hover {
  background: var(--ind-accent-soft);
}

.mob-ind-detail-head {
  padding: 1.25rem 1.25rem 1rem;
  border-bottom: 1px solid var(--card-border);
}

.mob-ind-detail-label {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ind-accent);
  margin-bottom: 0.25rem;
}

.mob-ind-detail-title {
  font-size: 1.1875rem;
  font-weight: 700;
  color: var(--color-heading);
  line-height: 1.2;
  margin-bottom: 0.5rem;
}

.mob-ind-detail-body {
  font-size: 0.875rem;
  color: var(--res-desc);
  line-height: 1.5;
  margin-bottom: 0.75rem;
}

.mob-ind-detail-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--ind-accent);
  text-decoration: none;
}

.mob-ind-sublist {
  list-style: none;
  padding: 0.625rem 1rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.mob-ind-subitem {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.5rem;
  border-radius: 0.5rem;
  text-decoration: none;
  color: var(--color-heading);
  font-size: 0.9375rem;
  transition: background-color 0.18s ease;
}

.mob-ind-subitem:not(.is-disabled):hover {
  background: var(--res-item-hover);
}

.mob-ind-subitem.is-disabled {
  opacity: 0.45;
  pointer-events: none;
}

.mob-ind-subicon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ind-accent);
}

.mobile-ind-trigger {
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0;
}

@media (min-width: 48rem) {
  .mob-ind-overlay {
    align-items: center;
    padding: 1.5rem;
  }

  .mob-ind-sheet {
    border-radius: 1.25rem;
    min-height: 0;
    transform: translateY(16px);
    opacity: 0;
    transition:
      transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
      opacity 0.3s ease;
    box-shadow:
      0 4px 6px rgba(0, 0, 0, 0.12),
      0 24px 64px rgba(0, 0, 0, 0.35),
      0 0 0 1px rgba(255, 255, 255, 0.05);
  }

  .mob-ind-overlay.is-open .mob-ind-sheet {
    transform: translateY(0);
    opacity: 1;
  }
}

@media (min-width: 80rem) {
  .mob-ind-overlay {
    display: none !important;
  }
}

.header-burger-button .header-burger-button-line {
	-webkit-transform-origin: center;
	-ms-transform-origin: center;
	transform-origin: center;
	-webkit-transition: opacity var(--transition-duration) ease,
		-webkit-transform var(--transition-duration) ease;
	transition: opacity var(--transition-duration) ease,
